/**
 * Embeds the Word templates of `templates/` into `src/documents/templates.generated.ts` (see
 * src/documents/template-files.ts). Run after editing a template: pnpm --filter @ocop/infra templates:embed
 */
import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { TEMPLATE_FILES } from "../src/documents/template-files";

const root = path.resolve(import.meta.dirname, "..");
const lines = [
  "// Generated by scripts/embed-templates.ts from templates/*.docx. Do not edit by hand.",
  'import type { DocumentTemplate } from "@ocop/core";',
  "",
  "export const EMBEDDED_TEMPLATES: Record<DocumentTemplate, string> = {",
];
for (const [template, file] of Object.entries(TEMPLATE_FILES)) {
  const base64 = (await readFile(path.join(root, "templates", file))).toString("base64");
  lines.push(`  ${template}: "${base64}",`);
}
lines.push("};", "");
await writeFile(path.join(root, "src/documents/templates.generated.ts"), lines.join("\n"));
console.log(`Embedded ${Object.keys(TEMPLATE_FILES).length} templates`);
